(46487, 'Nahum 3:1', 'Nahum', 3, 1, 'افسوس په حال ستا ای خونړی ښاره چې یې ډک له دروغو او لوټ او تالان نه او هېڅ وخت بې قتلونو نه یې', 'افسوس په حال ستا ای خونری شاره چې یې دک له دروغو او لوت او تالان نه او هېچ وخت بې قتلونو نه یې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46488, 'Nahum 3:2', 'Nahum', 3, 2, 'غوږ ونیسئ: د قمچینې کړپهار ته، د ارابو شورماشور ته د اسونو تېزو منډو، د ګاډیو درزهار ته', 'غوز ونیسی: د قمچینې کرپهار ته، د ارابو شورماشور ته د اسونو تېزو مندو، د ګادیو درزهار ته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46489, 'Nahum 3:3', 'Nahum', 3, 3, 'اس سواران کوي حملې تورې پړقیږي او نېزې ځلیږي دي جوړې شوې ډېرۍ د مړو دي بې‌شمېره مړي عسکر ښوییږي په هغو باندې', 'اس سواران کوی حملې تورې پرقیزی او نېزې جلیزی دی جورې شوې دېری د مرو دی بې‌شمېره مری عسکر شوییزی په هغو باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46490, 'Nahum 3:4', 'Nahum', 3, 4, 'ورکول کیږي سزا فاحشې نینوا ته هغې جذابې او وژونکې جادوګرې ته هغې وکړله جادو په قومونو باندې او غلامان یې کړل', 'ورکول کیزی سزا فاحشې نینوا ته هغې جذابې او وژونکې جادوګرې ته هغې وکرله جادو په قومونو باندې او غلامان یې کرل', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46491, 'Nahum 3:5', 'Nahum', 3, 5, 'مطلق قادر څښتن وایي: نینوا زه یمه ستا په خلاف ستا نه به وباسم کالي زه به ښکاره کړمه قومونو ته ستا لوڅوالی او پاچاهیو ته به وشرموم تا', 'مطلق قادر چشتن وایی: نینوا زه یمه ستا په خلاف ستا نه به وباسم کالی زه به شکاره کرمه قومونو ته ستا لوچوالی او پاچاهیو ته به وشرموم تا', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46492, 'Nahum 3:6', 'Nahum', 3, 6, 'تا به پټه کړمه په چټلۍ کې زه به ګورمه په سپکه سترګه تاته او تا نه به جوړه تماشه کړمه زه', 'تا به پته کرمه په چتلی کې زه به ګورمه په سپکه سترګه تاته او تا نه به جوره تماشه کرمه زه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46493, 'Nahum 3:7', 'Nahum', 3, 7, 'هرڅوک چې وویني تا نو تا نه به مخ اړوي هغوی به وایي چې ورانه شوې نینوا وبه کړي څوک ویر د هغې دپاره؟ څوک به ورکړي تسلي هغې ته؟', 'هرچوک چې ووینی تا نو تا نه به مخ اروی هغوی به وایی چې ورانه شوې نینوا وبه کری چوک ویر د هغې دپاره؟ چوک به ورکری تسلی هغې ته؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46494, 'Nahum 3:8', 'Nahum', 3, 8, 'ای نینوا، ایا ته د مصر د پایتخت تیبس نه ښه یې؟ هغې هم یو سیند درلود چې د هغې ساتنه وکړي یعنې د نیل سیند د هغې دفاع کوله.', 'ای نینوا، ایا ته د مصر د پایتخت تیبس نه شه یې؟ هغې هم یو سیند درلود چې د هغې ساتنه وکری یعنې د نیل سیند د هغې دفاع کوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46495, 'Nahum 3:9', 'Nahum', 3, 9, 'هغې په ایتوپیا او مصر باندې حکومت کاوه. د هغې د قدرت کوم حد نه ؤ. فوط او لیبیا د هغې ملګري وو.', 'هغې په ایتوپیا او مصر باندې حکومت کاوه. د هغې د قدرت کوم حد نه و. فوط او لیبیا د هغې ملګری وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46496, 'Nahum 3:10', 'Nahum', 3, 10, 'خو بیاهم د تیبس خلک د اسیرانو په توګه په جلاوطنۍ بوتلل شول. د هرې کوڅې په سر کې د هغوی ماشومان وغورځول شول او ووژل شول. د هغوی مشران په زنځیرونو کې بوتلل شول او د دښمن عسکرو په خپل منځ کې د هغو د وېشلو دپاره پچه واچوله.', 'خو بیاهم د تیبس خلک د اسیرانو په توګه په جلاوطنی بوتلل شول. د هرې کوچې په سر کې د هغوی ماشومان وغورجول شول او ووژل شول. د هغوی مشران په زنجیرونو کې بوتلل شول او د دشمن عسکرو په خپل منج کې د هغو د وېشلو دپاره پچه واچوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46497, 'Nahum 3:11', 'Nahum', 3, 11, 'ای نینوا، ته به هم لکه د یو شرابي په شان نشه شې! ته به کوښښ کوې چې پټه شې او د دښمن څخه به پناه غواړې.', 'ای نینوا، ته به هم لکه د یو شرابی په شان نشه شې! ته به کوشش کوې چې پته شې او د دشمن چخه به پناه غوارې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46498, 'Nahum 3:12', 'Nahum', 3, 12, 'ستا ټولې کلاګانې به د پخو انځرو په شان وي. کله چې څوک دا ونې وخوځوي، نو مېوه به یې د هغه خولې ته ورولویږي!', 'ستا تولې کلاګانې به د پخو انجرو په شان وی. کله چې چوک دا ونې وخوجوی، نو مېوه به یې د هغه خولې ته ورولویزی!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46499, 'Nahum 3:13', 'Nahum', 3, 13, 'ستا عسکر د ښځو په شان دي او ستا د وطن دروازې ستا د دښمنانو پرمخ خلاصې دي. اور به ستا د دروازو اړمونه وسوځوي.', 'ستا عسکر د شجو په شان دی او ستا د وطن دروازې ستا د دشمنانو پرمخ خلاصې دی. اور به ستا د دروازو ارمونه وسوجوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46500, 'Nahum 3:14', 'Nahum', 3, 14, 'د محاصرې دپاره تیاره شه او اوبه ذخیره کړه! خپلې جنګي کلاګانې قوي کړه! د خښتو د جوړولو دپاره خټه جوړه کړه او قالبونه تیار کړه!', 'د محاصرې دپاره تیاره شه او اوبه ذخیره کره! خپلې جنګی کلاګانې قوی کره! د خشتو د جورولو دپاره خته جوره کره او قالبونه تیار کره!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46501, 'Nahum 3:15', 'Nahum', 3, 15, 'ته چې هرڅه کوې، خو ته به په اور کې وسوځې او یا به په جنګ کې مړه شې. ته به داسې له منځه لاړه شې لکه څنګه چې ملخان فصلونه خوري. تاسو د ملخانو په شان زیات شوي یئ!', 'ته چې هرچه کوې، خو ته به په اور کې وسوجې او یا به په جنګ کې مره شې. ته به داسې له منجه لاره شې لکه چنګه چې ملخان فصلونه خوری. تاسو د ملخانو په شان زیات شوی یی!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46502, 'Nahum 3:16', 'Nahum', 3, 16, 'ستا د سوداګرانو شمېر د اسمان د ستورو نه زیات دی! خو اوس هغوی به داسې لاړ شي، لکه ملخان چې خپل وزرونه خپاره کړي او والوزي.', 'ستا د سوداګرانو شمېر د اسمان د ستورو نه زیات دی! خو اوس هغوی به داسې لار شی، لکه ملخان چې خپل وزرونه خپاره کری او والوزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46503, 'Nahum 3:17', 'Nahum', 3, 17, 'ستا ساتونکي او مامورین د هغو ملخانو د سیل په شان دي چې په یخه ورځ په دېوالونو باندې ناست وي. خو کله چې لمر راښکاره شي، نو هغوی الوزي او هېڅوک نه پوهیږي چې هغوی چېرته لاړل!', 'ستا ساتونکی او مامورین د هغو ملخانو د سیل په شان دی چې په یخه ورج په دېوالونو باندې ناست وی. خو کله چې لمر راشکاره شی، نو هغوی الوزی او هېچوک نه پوهیزی چې هغوی چېرته لارل!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46504, 'Nahum 3:18', 'Nahum', 3, 18, 'ای د آشور امپراتوره، ستا حاکمان مړه شوي او ستا درانه خلک په ابدي خوب باندې ویده شوي دي! ستا خلک په غرونو باندې خواره واره شوي دي او هېڅوک نشته چې هغوی بېرته خپلو کورونو ته راولي.', 'ای د اشور امپراتوره، ستا حاکمان مره شوی او ستا درانه خلک په ابدی خوب باندې ویده شوی دی! ستا خلک په غرونو باندې خواره واره شوی دی او هېچوک نشته چې هغوی بېرته خپلو کورونو ته راولی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46505, 'Nahum 3:19', 'Nahum', 3, 19, 'ستا د زخمونو علاج نشته او ستا پرهارونه به جوړ نه شي. هرڅوک چې ستا د بربادۍ نه خبریږي، نو د خوشحالۍ نه خپل لاسونه پړقوي. ایا داسې څوک شته چې ستا د ظلم نه خلاص شوی وي؟', 'ستا د زخمونو علاج نشته او ستا پرهارونه به جور نه شی. هرچوک چې ستا د بربادی نه خبریزی، نو د خوشحالی نه خپل لاسونه پرقوی. ایا داسې چوک شته چې ستا د ظلم نه خلاص شوی وی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_3_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46506, 'Exodus 40:1', 'Exodus', 40, 1, 'بیا څښتن موسی ته وویل:', 'بیا چشتن موسی ته وویل:', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46507, 'Exodus 40:2', 'Exodus', 40, 2, '«د لومړۍ میاشتې په لومړۍ ورځ سپېڅلې خېمه ودروه.', '«د لومری میاشتې په لومری ورج سپېچلې خېمه ودروه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46508, 'Exodus 40:3', 'Exodus', 40, 3, 'په هغې کې د لوظ صندوق چې لس حکمونه په کې دي، کېږده او هغه په پردې باندې پټ کړه.', 'په هغې کې د لوظ صندوق چې لس حکمونه په کې دی، کېزده او هغه په پردې باندې پت کره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46509, 'Exodus 40:4', 'Exodus', 40, 4, 'مېز دننه راوړه او سامان ورباندې کېږده. همدارنګه څراغدان هم دننه راوړه او څراغونه ورباندې کېږده.', 'مېز دننه راوره او سامان ورباندې کېزده. همدارنګه چراغدان هم دننه راوره او چراغونه ورباندې کېزده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46510, 'Exodus 40:5', 'Exodus', 40, 5, 'د سرو زرو د خوشبویۍ د سوځولو د قربانۍ ځای د لوظ د صندوق په مخکې کېږده او د خېمې په دروازه باندې پرده ځوړنده کړه.', 'د سرو زرو د خوشبویی د سوجولو د قربانی جای د لوظ د صندوق په مخکې کېزده او د خېمې په دروازه باندې پرده جورنده کره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46511, 'Exodus 40:6', 'Exodus', 40, 6, 'د سوځېدونکې نذرانې د قربانۍ ځای د سپېڅلې خېمې د دروازې په مخکې کېږده.', 'د سوجېدونکې نذرانې د قربانی جای د سپېچلې خېمې د دروازې په مخکې کېزده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
