(46533, 'Exodus 40:28', 'Exodus', 40, 28, 'بیا یې پرده د خېمې په دروازه کې ځوړنده کړه.', 'بیا یې پرده د خېمې په دروازه کې جورنده کره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46534, 'Exodus 40:29', 'Exodus', 40, 29, 'لکه څنګه چې څښتن حکم کړی ؤ، هغه د سوځېدونکې نذرانې د قربانۍ ځای د خېمې دروازې ته نژدې ودروله او په هغې باندې یې سوځېدونکې او د غلې دانې نذرانې وړاندې کړې.', 'لکه چنګه چې چشتن حکم کری و، هغه د سوجېدونکې نذرانې د قربانی جای د خېمې دروازې ته نژدې ودروله او په هغې باندې یې سوجېدونکې او د غلې دانې نذرانې وراندې کرې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46535, 'Exodus 40:30', 'Exodus', 40, 30, 'تشت یې د خېمې او د قربانۍ د ځای ترمنځ کېښود او د وینځلو دپاره یې اوبه په کې واچولې', 'تشت یې د خېمې او د قربانی د جای ترمنج کېشود او د وینجلو دپاره یې اوبه په کې واچولې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46536, 'Exodus 40:31', 'Exodus', 40, 31, 'او موسی، هارون او د هغه زامنو به د هغه څخه د خپلو لاسونو او پښو د وینځلو دپاره کار اخیست.', 'او موسی، هارون او د هغه زامنو به د هغه چخه د خپلو لاسونو او پشو د وینجلو دپاره کار اخیست.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_31.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46537, 'Exodus 40:32', 'Exodus', 40, 32, 'هرکله به چې هغوی خېمې ته ورننوتل، یا به د قربانۍ ځای ته ورتلل، نو خپل لاسونه او پښې به یې وینځلې، لکه څنګه چې څښتن موسی ته حکم کړی ؤ.', 'هرکله به چې هغوی خېمې ته ورننوتل، یا به د قربانی جای ته ورتلل، نو خپل لاسونه او پشې به یې وینجلې، لکه چنګه چې چشتن موسی ته حکم کری و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_32.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46538, 'Exodus 40:33', 'Exodus', 40, 33, 'بیا موسی د خېمې او د قربانۍ د ځای ګردچاپېره حوېلۍ جوړه کړه او د حوېلۍ په دروازې باندې یې پرده ځوړنده کړه. نو موسی کار پای ته ورساوه.', 'بیا موسی د خېمې او د قربانی د جای ګردچاپېره حوېلی جوره کره او د حوېلی په دروازې باندې یې پرده جورنده کره. نو موسی کار پای ته ورساوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_33.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46539, 'Exodus 40:34', 'Exodus', 40, 34, 'بیا ورېځ خېمه پټه کړه او د څښتن د جلال څخه ډکه شوه.', 'بیا ورېج خېمه پته کره او د چشتن د جلال چخه دکه شوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_34.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46540, 'Exodus 40:35', 'Exodus', 40, 35, 'نو له دې امله موسی نه شو کولای چې خېمې ته ورننوځي.', 'نو له دې امله موسی نه شو کولای چې خېمې ته ورننوجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_35.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46541, 'Exodus 40:36', 'Exodus', 40, 36, 'اسراییلیانو به یوازې هغه وخت خپل کمپ بل ځای ته انتقالاوه چې کله به ورېځ د خېمې څخه پورته کېدله.', 'اسراییلیانو به یوازې هغه وخت خپل کمپ بل جای ته انتقالاوه چې کله به ورېج د خېمې چخه پورته کېدله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_36.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46542, 'Exodus 40:37', 'Exodus', 40, 37, 'ترڅو پورې چې ورېځ به هلته ولاړه وه، نو هغوی به خپل کمپ نه انتقالاوه.', 'ترچو پورې چې ورېج به هلته ولاره وه، نو هغوی به خپل کمپ نه انتقالاوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_37.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46543, 'Exodus 40:38', 'Exodus', 40, 38, 'د ټولو سفرونو په دوران کې ټولو اسراییلیانو د ورځې له خوا د څښتن د حضور ورېځ د خېمې دپاسه لیدلی شوه او د شپې له خوا به یې لیدل چې په ورېځ کې اور بلیږي.', 'د تولو سفرونو په دوران کې تولو اسراییلیانو د ورجې له خوا د چشتن د حضور ورېج د خېمې دپاسه لیدلی شوه او د شپې له خوا به یې لیدل چې په ورېج کې اور بلیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_40_38.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
